#!/usr/bin/env bash
# Builds tablet/Image.efi — a correct PE32+/EFI wrapper around the Silver
# kernel Image — and optionally packs it into an Android boot image.
#
#   ./tablet/build_efi_img.sh            # build Image.efi only
#   ./tablet/build_efi_img.sh --build    # rebuild the tablet kernel first
#   ./tablet/build_efi_img.sh --pack     # also pack tablet/boot_silver.img (v4)
#
# The PE header is generated by lld-link (not hand-laid): the previous
# build_efi_wrapper.py had the optional-header fields shifted by 10 bytes, so
# Subsystem landed at 0x3A instead of 0x44 and UEFI LoadImage rejected the
# image (QCDUMP). lld-link computes AddressOfEntryPoint / SizeOfImage / the
# section table correctly.
set -euo pipefail
cd "$(dirname "$0")/.."

if [ "${1:-}" = "--build" ] || [ "${1:-}" = "--pack" ]; then
    echo "==> Building tablet kernel (no_std,tablet)"
    cargo build --release --target aarch64-unknown-none \
        --no-default-features --features "no_std,tablet"
fi

KERNEL=target/aarch64-unknown-none/release/silver_microkernel
if [ ! -f "$KERNEL" ]; then
    echo "ERROR: kernel not found at $KERNEL (run with --build)" >&2
    exit 1
fi

echo "==> Entry point (linked, must be 0xA8000000):"
llvm-readelf -h "$KERNEL" | grep -i entry || aarch64-linux-gnu-readelf -h "$KERNEL" | grep -i entry

echo "==> objcopy raw kernel WITHOUT padding (the EFI stub copies exactly this)"
aarch64-linux-gnu-objcopy -O binary "$KERNEL" tablet/Image.nopad
ls -l tablet/Image.nopad

echo "==> Raw arm64 Image for the FAT32 root (linuxdirect /Image)"
cp tablet/Image.nopad tablet/Image
echo "==> ARM64 Image header check (code0/text_offset/image_size/magic):"
xxd -l 64 tablet/Image
python3 - <<'EOF'
import struct, os
d = open('tablet/Image', 'rb').read(0x40)
assert d[0x38:0x3C] == b'ARMd', 'missing ARMd magic'
assert struct.unpack_from('<Q', d, 8)[0] == 0, 'text_offset must be 0'
size = struct.unpack_from('<Q', d, 0x10)[0]
fsize = os.path.getsize('tablet/Image')
assert 0 < size < fsize + 16 * 1024 * 1024, 'bad image_size'
print(f'header OK: image_size={size:#x} (file {fsize:#x}, '
      f'delta=bss) text_offset=0 magic=ARMd')
EOF

echo "==> assembling efi_stub.S -> COFF object (embeds Image.nopad via .incbin)"
clang --target=aarch64-unknown-windows-msvc -ffreestanding \
    -c tablet/efi_stub.S -o tablet/efi_stub.obj

echo "==> linking PE32+ EFI application"
# ImageBase must be 0: both the stock ColorOS PE kernel and QCOMRAMP.EFI use
# ImageBase=0, and the stock kernel has NO .reloc section — so a PIC image at
# base 0 is exactly what this device's LoadImage accepts. (lld-link forces
# DYNAMIC_BASE/HIGH_ENTROPY_VA on arm64; those are Windows ASLR hints that
# EDK2's loader ignores, and QCOMRAMP.EFI carries them too.)
lld-link /subsystem:efi_application /entry:efi_entry /machine:arm64 \
    /base:0 \
    /out:tablet/Image.efi tablet/efi_stub.obj

echo "==> PE header check (expect Machine=ARM64, Subsystem=EFI_APPLICATION, Magic=0x20B):"
llvm-readobj --file-headers tablet/Image.efi | grep -E "Machine|Subsystem|Magic|AddressOfEntryPoint|SectionCount|SizeOfImage|SizeOfHeaders"

echo "==> Entry code disassembly (sanity: adr/adrp resolved, no dangling relocs):"
llvm-objdump -d --no-show-raw-insn tablet/Image.efi | head -40 || true

if [ "${1:-}" = "--pack" ]; then
    echo "==> Packing boot_silver.img (header v4, like the stock MZ/PE kernel)"
    mkbootimg \
        --kernel tablet/Image.efi \
        --header_version 4 \
        --os_version 13.0.0 --os_patch_level 2023-04 \
        -o tablet/boot_silver.img
    ls -l tablet/boot_silver.img
fi

echo "==> Done: tablet/Image.efi"
ls -l tablet/Image.efi
